/** The instrument ids the bank really covers (the preview lists these). */
export const TONE_BANK_INSTRUMENTS: readonly PreviewInstrumentId[] = ['piano', 'strings', 'guitar'];

/**
 * The module id of one tone, or null when the bank has nothing for it.
 * The range covers the editor's own pitch clamp, so null is a real bug, not a
 * silent note: the caller says so instead of playing the wrong pitch.
 */
export function toneSourceFor(
  instrument: PreviewInstrumentId | string | null | undefined,
  midi: number,
): number | null {
  const table = BANK[instrument as PreviewInstrumentId] ?? BANK.piano;
  const value = Math.round(Number(midi));
  if (!Number.isFinite(value)) return null;
  return table[value] ?? null;
}
